<?php
declare(strict_types=1);
function smtp_read($socket,array $codes,string $stage='SMTP'):string{$response='';do{$line=fgets($socket,515);if($line===false)throw new RuntimeException($stage.': servidor sem resposta.');$response.=$line;}while(isset($line[3])&&$line[3]==='-');$code=(int)substr($response,0,3);if(!in_array($code,$codes,true))throw new RuntimeException($stage.': resposta '.$code.'.');return $response;}
function smtp_write($socket,string $command,array $codes,string $stage):void{fwrite($socket,$command."\r\n");smtp_read($socket,$codes,$stage);}
function send_portal_mail(string $to,string $name,string $subject,string $html):void{$m=mail_settings();$host=trim((string)($m['host']??''));$port=(int)($m['port']??465);if($host===''||empty($m['username'])||empty($m['password']))throw new RuntimeException('Configuração: existem campos obrigatórios vazios.');$context=stream_context_create(['ssl'=>['verify_peer'=>true,'verify_peer_name'=>true,'peer_name'=>$host]]);$socket=@stream_socket_client('ssl://'.$host.':'.$port,$errno,$errstr,20,STREAM_CLIENT_CONNECT,$context);if(!$socket)throw new RuntimeException('Conexão SSL: falha '.$errno.'.');stream_set_timeout($socket,20);smtp_read($socket,[220],'Conexão SMTP');smtp_write($socket,'EHLO newsiga.com.br',[250],'Identificação');smtp_write($socket,'AUTH LOGIN',[334],'Autenticação');smtp_write($socket,base64_encode(trim((string)$m['username'])),[334],'Usuário SMTP');smtp_write($socket,base64_encode((string)$m['password']),[235],'Senha SMTP');$from=$m['from_email']??$m['username'];smtp_write($socket,'MAIL FROM:<'.$from.'>',[250],'Remetente');smtp_write($socket,'RCPT TO:<'.$to.'>',[250,251],'Destinatário');smtp_write($socket,'DATA',[354],'Conteúdo');$headers=['Date: '.date(DATE_RFC2822),'From: '.($m['from_name']??'Newsiga').' <'.$from.'>','To: '.$name.' <'.$to.'>','Reply-To: '.($m['reply_to']??$from),'Subject: =?UTF-8?B?'.base64_encode($subject).'?=','MIME-Version: 1.0','Content-Type: text/html; charset=UTF-8','Content-Transfer-Encoding: base64','Message-ID: <'.bin2hex(random_bytes(12)).'@newsiga.com.br>'];$body=chunk_split(base64_encode($html));$message=implode("\r\n",$headers)."\r\n\r\n".$body;$message=preg_replace('/^\./m','..',$message);fwrite($socket,$message."\r\n.\r\n");smtp_read($socket,[250],'Envio');smtp_write($socket,'QUIT',[221],'Encerramento');fclose($socket);}
function recovery_email(string $name,string $link):string{$safe=htmlspecialchars($name,ENT_QUOTES,'UTF-8');$safeLink=htmlspecialchars($link,ENT_QUOTES,'UTF-8');return '<!doctype html><html><body style="margin:0;background:#f2f4ef;font-family:Arial,sans-serif;color:#0c2a23"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:36px 16px"><table role="presentation" width="560" cellpadding="0" cellspacing="0" style="max-width:100%;background:#fff;border:1px solid #d9dfda"><tr><td style="padding:36px"><div style="font-size:28px;font-weight:800;letter-spacing:-2px">newsiga</div><p style="margin-top:38px;font-size:11px;letter-spacing:2px;font-weight:bold;color:#64766f">ÁREA DO CLIENTE</p><h1 style="font-size:30px;line-height:1.15;margin:12px 0 18px">Crie uma nova senha</h1><p>Olá, '.$safe.'. Recebemos uma solicitação para definir uma nova senha para seu acesso.</p><p style="margin:28px 0"><a href="'.$safeLink.'" style="display:inline-block;background:#0c2a23;color:#fff;text-decoration:none;padding:15px 22px;font-weight:bold">Criar nova senha</a></p><p style="font-size:13px;color:#64766f">Este link expira em 60 minutos e só pode ser usado uma vez. Se você não fez esta solicitação, ignore esta mensagem.</p></td></tr></table></td></tr></table></body></html>';}
